mapper.select:
SELECT A.ACTION_ID AS actionId , A.ACTION_NAME AS actionName , A.TOP_MENU_ID AS topMenuId , TOP_MENU.TITLE AS topMenuName , A.MID_MENU_ID AS midMenuId , MID_MENU.TITLE AS midMenuName , A.BTM_MENU_ID AS btmMenuId , BTM_MENU.TITLE AS btmMenuName FROM ACTION A LEFT JOIN MENU TOP_MENU ON A.TOP_MENU_ID = TOP_MENU.ID LEFT JOIN MENU MID_MENU ON A.MID_MENU_ID = MID_MENU.ID LEFT JOIN MENU BTM_MENU ON A.BTM_MENU_ID = BTM_MENU.ID WHERE 1 = 1
AND A.TOP_MENU_ID = #{topMenuId}
AND A.MID_MENU_ID = #{midMenuId}
AND A.BTM_MENU_ID = #{btmMenuId}
AND A.ACTION_NAME LIKE '%' || #{actionName} || '%'
ORDER BY A.ACTION_ID DESC

mapper.update:
UPDATE ACTION
   SET(
        ACTION_NAME = #{actionName}
      , TOP_MENU_ID = #{topMenuId}
      , MID_MENU_ID = #{midMenuId}
      , BTM_MENU_ID = #{btmMenuId})
  WHERE ACTION_ID = #{actionId}
